// HTTP check only for 4zida: CityExpert returns 200 even for deleted listings, Nekretnine.rs and Halo return 403 (bot protection).
const r = $('GetListings').first().json;
const fields = (r.schema?.fields || []).map(f => f.name);
return (r.rows || [])
  .map(row => Object.fromEntries(row.f.map((c, i) => [fields[i], c.v])))
  .filter(l => l.izvor === '4zida')
  .map(l => ({ json: l }));

// What counts as inactive:
// - 4zida: the link returns 404/410 or redirects to a page without the listing id
// - CityExpert: the listing is not in the current search. Source - CityExpert is called with allPages = true and reads
//   every page (max 10 × 30); if it hit that limit the list may be incomplete → CityExpert is skipped
//   (bug on 18.11.: only page 1 was read, so listings on page 2 were deleted)
// - Nekretnine.rs, Halo: cannot be checked (bot protection, 403) → deleted once they are older than MAX_DANA days
// DRY_RUN = true: report only, nothing is deleted.
const DRY_RUN = false;
const MAX_DANA = 21;
const CE_MAX = 10 * 30;
const q = $('GetListings').first().json;
const fields = (q.schema?.fields || []).map(f => f.name);
const all = (q.rows || []).map(row => Object.fromEntries(row.f.map((c, i) => [fields[i], c.v])));
const dead = [];
const bySource = {};
const statuses = {};
const add = l => { dead.push(l.id); bySource[l.izvor] = (bySource[l.izvor] || 0) + 1; };

const src = $('ToItems').all().map(i => i.json);
let unknown4zida = 0;
$input.all().forEach((it, i) => {
  const l = src[i];
  if (!l) return;
  const r = it.json;
  const status = Number(r.statusCode ?? 0);
  statuses[status] = (statuses[status] || 0) + 1;
  const key = String(l.id).split('_').slice(1).join('_');
  const loc = String(r.headers?.location ?? '');
  if (status === 404 || status === 410) add(l);
  else if (status >= 300 && status < 400 && loc && !loc.includes(key)) add(l);
  else if (!(status >= 200 && status < 400)) unknown4zida++;
});

let ce = [];
try { ce = $('RunCityExpert').all().map(i => i.json); } catch (e) { ce = []; }
const ceIds = new Set(ce.map(x => x.id).filter(Boolean));
const ceOk = ceIds.size >= 5 && ceIds.size < CE_MAX && !ce.some(x => x.error);
if (ceOk) all.filter(l => l.izvor === 'cityexpert' && !ceIds.has(l.id)).forEach(add);

const checked = all.filter(l => l.izvor === '4zida').length + (ceOk ? all.filter(l => l.izvor === 'cityexpert').length : 0);
// If more than half of the checked listings look "dead", the site probably changed its responses → delete nothing.
if (checked >= 10 && dead.length > checked * 0.5) {
  throw new Error(`Čišćenje prekinuto: ${dead.length} od ${checked} proverenih oglasa izgleda neaktivno`);
}

// Nekretnine.rs and Halo: by age (days since first ingest).
const unverifiable = all.filter(l => l.izvor === 'nekretnine' || l.izvor === 'halo');
const expired = unverifiable.filter(l => Number(l.starost) > MAX_DANA);
expired.forEach(add);
const unknown = unverifiable.length - expired.length + unknown4zida + (ceOk ? 0 : all.filter(l => l.izvor === 'cityexpert').length);

const safe = dead.filter(id => /^[A-Za-z0-9_-]+$/.test(id));
const list = safe.map(id => `'${id}'`).join(', ');
const T = '`stan-hunter.stan_hunter.listings`';
return [{ json: {
  dry_run: DRY_RUN,
  checked,
  dead: safe,
  expired: expired.length,
  max_dana: MAX_DANA,
  unknown,
  bySource,
  statuses,
  cityexpert_aktivnih: ceIds.size,
  cityexpert_provereno: ceOk,
  backupQuery: { query: 'CREATE OR REPLACE TABLE `stan-hunter.stan_hunter.listings_backup` AS SELECT * FROM ' + T, useLegacySql: false, location: 'EU', timeoutMs: 60000 },
  deleteQuery: { query: `CREATE OR REPLACE TABLE ${T} PARTITION BY DATE(upisano) AS SELECT * FROM ${T} WHERE id NOT IN (${list || "''"}) QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY upisano DESC) = 1`, useLegacySql: false, location: 'EU', timeoutMs: 60000 }
} }];
